contract LockThenWipeTest is Test {
    address private constant BORROWER = address(0xB0B);
    address private constant OTHER = address(0x07E);

    MockIMD private imd;
    LwFeed private primary;
    ParameterizedVault private vault;
    ImdUSD private stable;

    function usd(uint256 dollars) private pure returns (uint256) {
        return dollars / 2000;
    }

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new LwAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        primary = new LwFeed(usd(1 ether)); // IMD = $1
        LwFeed health = new LwFeed(0.85 ether); // mat 170, gap 50
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(new LwMirror(primary))
        );
        stable = vault.stablecoin();
        vm.startPrank(APPROVED_OPERATOR);
        imd.mint(BORROWER, 10_000 ether);
        imd.mint(OTHER, 10_000 ether);
        vm.stopPrank();
        vm.prank(BORROWER);
        imd.approve(address(vault), type(uint256).max);
        vm.prank(OTHER);
        imd.approve(address(vault), type(uint256).max);

        // The retry panel's below-par book: the borrower in the 170-200% band, OTHER underwater, all warm.
        vm.startPrank(BORROWER);
        vault.lock(5_790 ether);
        vault.draw(1_000 ether);
        vm.stopPrank();
        vm.startPrank(OTHER);
        vault.lock(5_100 ether);
        vault.draw(3_000 ether);
        stable.transfer(BORROWER, 3_000 ether);
        vm.stopPrank();
        primary.set(usd(0.294 ether)); // borrower 170.2%, OTHER 50%
        vm.prank(BORROWER);
        vault.lock(1);
        vm.prank(OTHER);
        vault.lock(1);
        vm.warp(block.timestamp + 3 days);
        assertApproxEqRel(vault.backingPerUnit(), 0.8004e18, 1e15, "below par");
    }

    /// Five transactions in one block: lock 540, wipe 140, cash 500 against self, free 540, draw 140.
    /// The position ends where a direct wipe of 140 leaves it, but the direct wipe keeps 140 in the supply
    /// (Position.excess) and this order keeps nothing. EXPECTED: the honest payout. ACTUAL: +3.6%.
    function test_aLockBeforeTheWipeMasksTheFallAndPaysThePremium() public {
        uint256 snap = vm.snapshotState();
        vm.prank(BORROWER);
        uint256 honest = vault.cash(500 ether, 0, BORROWER);
        vm.revertToState(snap);

        vm.prank(BORROWER);
        vault.lock(540 ether);
        vm.prank(BORROWER);
        vault.wipe(140 ether);
        vm.prank(BORROWER);
        uint256 churned = vault.cash(500 ether, 0, BORROWER);
        vm.prank(BORROWER);
        vault.free(540 ether);
        vm.prank(BORROWER);
        vault.draw(140 ether);
        emit log_named_uint("honest payout (raw IMD)", honest);
        emit log_named_uint("churned payout (raw IMD)", churned);
        assertLe(churned, honest + honest / 1_000, "a lock before the repayment must not raise what a redemption is paid");
    }
}

