contract FreeRelockPremiumTest is Test {
    address private constant BORROWER = address(0xB0B);
    address private constant OTHER = address(0x07E);

    MockIMD private imd;
    ParameterizedVault private vault;
    ImdUSD private stable;
    FrFeed private primary;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new FrAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        primary = new FrFeed(uint256(1 ether) * 1e18 / 2000 ether); // IMD = $1
        FrFeed health = new FrFeed(0.85 ether); // mat 170, gap 50
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(new FrMirror(primary))
        );
        stable = vault.stablecoin();
        vm.startPrank(APPROVED_OPERATOR);
        imd.mint(BORROWER, 10_000 ether);
        imd.mint(OTHER, 10_000 ether);
        vm.stopPrank();
        vm.prank(BORROWER);
        imd.approve(address(vault), type(uint256).max);
        vm.prank(OTHER);
        imd.approve(address(vault), type(uint256).max);

        // The retry panel's below-par book: the borrower in the 170-200% band, OTHER underwater, all warm.
        vm.startPrank(BORROWER);
        vault.lock(5_790 ether);
        vault.draw(1_000 ether);
        vm.stopPrank();
        vm.startPrank(OTHER);
        vault.lock(5_100 ether);
        vault.draw(3_000 ether);
        stable.transfer(BORROWER, 3_000 ether);
        vm.stopPrank();
        primary.set(uint256(0.294 ether) * 1e18 / 2000 ether); // borrower 170.2%, OTHER 50%
        vm.prank(BORROWER);
        vault.lock(1);
        vm.prank(OTHER);
        vault.lock(1);
        vm.warp(block.timestamp + 3 days);
        assertApproxEqRel(vault.backingPerUnit(), 0.8004e18, 1e15, "below par");
    }

    /// Five transactions: wipe 140 (term unchanged, excess 140), free 500 IMD (worth 147: releases the whole
    /// excess, the term's fall banked warm), lock 500 (the term is back, credited warm from the bank, no excess),
    /// cash 500 against the borrower, draw 140. EXPECTED: the payout of a world with no churn. ACTUAL: the payout
    /// is measured against a supply 140 smaller with the same backing.
    function test_freeAndRelockRestoresTheRepayThenRedeemPremium() public {
        uint256 snap = vm.snapshotState();
        vm.prank(BORROWER);
        uint256 honest = vault.cash(500 ether, 0, BORROWER);
        vm.revertToState(snap);

        vm.prank(BORROWER);
        vault.wipe(140 ether);
        vm.prank(BORROWER);
        vault.free(500 ether);
        vm.prank(BORROWER);
        vault.lock(500 ether);
        assertEq(vault.securedCollateral(), 5_790 ether + 5_100 ether + 2, "the numerator is back where it stood");
        (, uint256 lagSecured) = vault.laggedNow();
        assertApproxEqRel(lagSecured, vault.securedCollateral(), 1e15, "and it reads warm (credited from the bank)");
        vm.prank(BORROWER);
        uint256 churned = vault.cash(500 ether, 0, BORROWER);
        vm.prank(BORROWER);
        vault.draw(140 ether);
        assertLe(churned, honest + honest / 1_000, "a repayment, a withdrawal and a re-lock must not raise the payout");
    }
}

