contract ExcessFreeLockTest is Test {
    address private constant CHURNER = address(0xC4);
    address private constant UNDERWATER = address(0x07E);
    address private constant REDEEMER = address(0x5ED);

    MockIMD private imd;
    EflFeed private primary;
    ParameterizedVault private vault;
    ImdUSD private stable;

    function usd(uint256 dollars1e18) private pure returns (uint256) {
        // IMD/ETH in wei per 1e18 IMD, such that times Chainlink's 2000 USD/ETH it reads `dollars1e18`.
        return dollars1e18 / 2000;
    }

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new EflAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        primary = new EflFeed(usd(1 ether)); // IMD = $1
        EflFeed health = new EflFeed(0.85 ether); // mat 170, lull 6h, gap 50
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(new EflMirror(primary))
        );
        stable = vault.stablecoin();
        vm.startPrank(APPROVED_OPERATOR);
        imd.mint(CHURNER, 100_000 ether);
        imd.mint(UNDERWATER, 100_000 ether);
        imd.mint(address(vault.treasury()), 1_000 ether); // the redemption is reserve-funded: the Treasury pays
        vm.stopPrank();
        vm.prank(CHURNER);
        imd.approve(address(vault), type(uint256).max);
        vm.prank(UNDERWATER);
        imd.approve(address(vault), type(uint256).max);

        // UNDERWATER: 5,100 IMD against 3,000 imdUSD (170%). CHURNER: 18,000 IMD against 1,000 imdUSD.
        vm.startPrank(UNDERWATER);
        vault.lock(5_100 ether);
        vault.draw(3_000 ether);
        stable.transfer(REDEEMER, 300 ether);
        vm.stopPrank();
        vm.startPrank(CHURNER);
        vault.lock(18_000 ether);
        vault.draw(1_000 ether);
        vm.stopPrank();
        vm.warp(block.timestamp + 1 days);

        // IMD falls to $0.10. UNDERWATER is at 17%; CHURNER at 180%, its term now its whole collateral.
        primary.set(usd(0.1 ether));
        vm.prank(CHURNER);
        vault.lock(1); // re-prices the churner's term (the rise is cold, so let it warm)
        vm.warp(block.timestamp + 3 days);
        assertLt(vault.backingPerUnit(), 1e18, "the vault is below par: the premium is payable");
    }

    function test_freeThenLockReopensTheRepayThenRedeemPremium() public {
        uint256 backingBefore = vault.backingPerUnit();

        // Honest: what a 100 imdUSD redemption pays now.
        uint256 snapshot = vm.snapshotState();
        vm.prank(REDEEMER);
        uint256 honest = vault.cash(100 ether, 0, address(0));
        vm.revertToState(snapshot);

        // Tx 1: the churner repays 100 in the band; its term does not move, so the supply keeps the 100.
        uint256 debtBefore = vault.debtOf(CHURNER);
        vm.prank(CHURNER);
        vault.wipe(100 ether);
        uint256 repaid = debtBefore - vault.debtOf(CHURNER);
        assertApproxEqRel(vault.backingPerUnit(), backingBefore, 1e15, "58f73de holds: the repayment alone pays no premium");

        // Tx 2: free collateral worth exactly the principal repaid: the term falls by it and free releases the excess.
        uint256 freed = repaid * 1e18 / 0.1 ether;
        vm.prank(CHURNER);
        vault.free(freed);

        // Tx 3: lock it back. The term rises by the same amount and is credited warm from the churner's bank;
        // lock re-adds nothing to the excess.
        vm.prank(CHURNER);
        vault.lock(freed);

        // Tx 4: the redemption. EXPECTED: paid no more than the honest figure. ACTUAL: supply / (supply - repaid) more.
        uint256 backingAfter = vault.backingPerUnit();
        vm.prank(REDEEMER);
        uint256 churned = vault.cash(100 ether, 0, address(0));
        emit log_named_uint("honest payout (raw IMD)", honest);
        emit log_named_uint("churned payout (raw IMD)", churned);
        emit log_named_uint("backing before", backingBefore);
        emit log_named_uint("backing after wipe/free/lock", backingAfter);
        assertLe(churned, honest + honest / 10_000, "a repayment that left its backing behind must not raise the payout");

        // Tx 5: the churner redraws, and is where it started.
        vm.prank(CHURNER);
        vault.draw(repaid);
    }
}

