        vault.lock(1);
        vm.warp(vm.getBlockTimestamp() + 3 days);
    }

    /// A direct wipe of 140 keeps the 140 in the supply (the term did not move), so a redemption in the next
    /// transaction is paid the backing that stood before it. The same wipe with a lock of 540 one transaction
    /// earlier (raising the term, still debt-bound below 2 x 1,000 / 0.294) sees the term fall by 481 raw units, which
    /// is "worth" 141 > 140, so nothing is kept; the borrower then frees the 540 (no term change, nothing to
    /// release) and redraws the 140. Debt, supply and collateral end where they began; the redemption in between
    /// was paid above pro rata.
    function test_aLockBeforeTheWipeHidesTheRepaymentFromTheExcess() public {
        uint256 backing = vault.backingPerUnit();
        assertApproxEqRel(backing, 0.8004e18, 1e15, "below par");

        // The honest payout for 500 against the borrower, no churn.
        uint256 snap = vm.snapshotState();
        vm.prank(BORROWER);
        uint256 honest = vault.cash(500 ether, 0, BORROWER);
        vm.revertToState(snap);

        // The direct wipe, for reference: the 140 stays in the supply and the payout is the honest one.
        snap = vm.snapshotState();
        vm.prank(BORROWER);
        vault.wipe(140 ether);
        vm.prank(BORROWER);
        uint256 direct = vault.cash(500 ether, 0, BORROWER);
        vm.revertToState(snap);
        assertLe(direct, honest + honest / 1_000, "a direct wipe one transaction earlier does not raise the payout");

        // Five separate transactions (any gas price; no time needs to pass).
        vm.prank(BORROWER);
        vault.lock(540 ether);
        vm.prank(BORROWER);
        vault.wipe(140 ether);
        vm.prank(BORROWER);
        uint256 churned = vault.cash(500 ether, 0, BORROWER);
        vm.prank(BORROWER);
        vault.free(540 ether);
        vm.prank(BORROWER);
        vault.draw(140 ether);
        (uint256 collateral, uint256 debt) = vault.positions(BORROWER);
        assertEq(collateral, 5_790 ether + 1 - churned, "the collateral is where the direct route leaves it");
        assertApproxEqAbs(debt, 500 ether, 2 ether, "and so is the debt");

        // EXPECTED: the direct route's payout. ACTUAL: about 3.6% more, paid out of OTHER's backing.
        assertLe(churned, honest + honest / 1_000, "a lock before the wipe must not raise the payout");
    }

    /// The same churn with the redemption funded from the Treasury's reserve: the reserve pays above pro rata.
    function test_theReserveFundedRedemptionIsPaidThePremiumToo() public {
        address treasury = address(vault.treasury());
        vm.prank(APPROVED_OPERATOR);
        imd.mint(treasury, 400 ether);
        uint256 snap = vm.snapshotState();
        vm.prank(BORROWER);
        uint256 honest = vault.cash(100 ether, 0, address(0));
        vm.revertToState(snap);

        vm.prank(BORROWER);
        vault.lock(540 ether);
        vm.prank(BORROWER);
        vault.wipe(140 ether);
        vm.prank(BORROWER);
        uint256 churned = vault.cash(100 ether, 0, address(0));
        vm.prank(BORROWER);
        vault.free(540 ether);
        vm.prank(BORROWER);
        vault.draw(140 ether);
        assertLe(churned, honest + honest / 1_000, "a lock before the wipe must not raise the reserve payout");
    }
